options.getOption:
const N = 35;

const frame = context.panel.data.series[0];

if (!frame) {
  return {
    title: {
      text: "No data returned"
    }
  };
}

const rowField = frame.fields.find(f => f.name === "live_row");
const colField = frame.fields.find(f => f.name === "live_col");
const valueField =
  frame.fields.find(f => f.name === "_value") ||
  frame.fields.find(f => f.name === "live_value");

if (!rowField || !colField || !valueField) {
  return {
    title: {
      text: "Missing live_row, live_col, or value field"
    }
  };
}

function getVal(field, i) {
  return field.values.get ? field.values.get(i) : field.values[i];
}

let heatmapData = [];

for (let i = 0; i < valueField.values.length; i++) {
  const r = Number(getVal(rowField, i));
  const c = Number(getVal(colField, i));
  const v = Number(getVal(valueField, i));

  heatmapData.push([c, r, v]);
}

const maxValue = Math.max(...heatmapData.map(p => Number(p[2])), 1);
const countThreshold = maxValue * 0.85;
const hotPixels = heatmapData
  .filter(p => Number(p[2]) >= countThreshold)
  .map(p => [p[0], p[1], p[2]]);

return {

  animation: false,


  tooltip: {
    trigger: "item",
    formatter: function (p) {
      return "Row: " + p.value[1] +
        "<br>Col: " + p.value[0] +
        "<br>Value: " + p.value[2];
    }
  },

  xAxis: {
    type: 'category',
    name: "Col",
    data: Array.from({ length: N }, (_, i) => i),
    splitArea: { show: true },
    axisLine: { show: true }
  },
  yAxis: {
    type: 'category',
    name: "Row",
    data: Array.from({ length: N }, (_, i) => i),
    splitArea: { show: true },
    inverse: false,
    axisLine: { show: true }
  },
  grid: {
    left: 60,
    right: 100,
    top: 40,
    bottom: 40,
    containLabel: true,
  },

  visualMap: {
    min: 0,
    max: Math.max(maxValue * 0.7, 1),
    calculable: true,
    orient: "vertical",
    right: 10,
    top: "middle",

    inRange: {
      color: [
        "#440154",
        "#3b528b",
        "#21918c",
        "#5ec962",
        "#fde725"
      ]
    }
  },
  series: [
    {
      name: "Activity",
      type: "heatmap",
      data: heatmapData,
      label: { show: false }
    },
    {
      name: "Hot_Pixels",
      type: "scatter",
      data: hotPixels,
      symbol: "rect",
      symbolSize: 13,
      itemStyle: {
        color: "transparent",
        borderColor: "#ff0000",
        borderWidth: 2
      },
      tooltip: { show: false }    
    }
  ]
};

